package llmverify

import chisel3._
import chisel3.util._
import chiselFv._

class barrel4 extends Module with Formal {
  val io = IO(new Bundle {
    // Add outputs to preserve the registers for verification
    val b0 = Output(UInt(2.W))
    val b1 = Output(UInt(2.W))
    val b2 = Output(UInt(2.W))
    val b3 = Output(UInt(2.W))
    val r0 = Output(UInt(2.W))
    val r1 = Output(UInt(2.W))
    val r2 = Output(UInt(2.W))
    val r3 = Output(UInt(2.W))
  })

  // Define registers (2 bits wide as specified by [2-1:0])
  // Initialize to 0 to ensure valid initial state
  val b0 = RegInit(0.U(2.W))
  val b1 = RegInit(0.U(2.W))
  val b2 = RegInit(0.U(2.W))
  val b3 = RegInit(0.U(2.W))
  val r0 = RegInit(0.U(2.W))
  val r1 = RegInit(0.U(2.W))
  val r2 = RegInit(0.U(2.W))
  val r3 = RegInit(0.U(2.W))

  // Implement the valid function as a Chisel function
  def valid(b0: UInt, r0: UInt, b1: UInt, r1: UInt, b2: UInt, r2: UInt, b3: UInt, r3: UInt): Bool = {
    (b0 =/= r0 || b1 === r1) &&
    (b0 =/= r1 || b1 === r2) &&
    (b0 =/= r2 || b1 === r3) &&
    (b0 =/= r3 || b1 === r0) &&
    (b1 =/= r0 || b2 === r1) &&
    (b1 =/= r1 || b2 === r2) &&
    (b1 =/= r2 || b2 === r3) &&
    (b1 =/= r3 || b2 === r0) &&
    (b2 =/= r0 || b3 === r1) &&
    (b2 =/= r1 || b3 === r2) &&
    (b2 =/= r2 || b3 === r3) &&
    (b2 =/= r3 || b3 === r0) &&
    (b3 =/= r0 || b0 === r1) &&
    (b3 =/= r1 || b0 === r2) &&
    (b3 =/= r2 || b0 === r3) &&
    (b3 =/= r3 || b0 === r0)
  }

  // Handle state updates on each clock edge
  // In Chisel, RegInit handles reset automatically
  // The rotation happens on every clock cycle when not in reset

  // Rotate shifter contents up by one position
  // b0 gets b1, b1 gets b2, b2 gets b3, b3 gets b0 (old value)
  val b0_old = RegNext(b0) // Store previous value of b0
  b0 := b1
  b1 := b2
  b2 := b3
  b3 := b0_old

  // Register file holds its contents perpetually (no updates)
  // r0, r1, r2, r3 remain unchanged as they are RegInit with no further assignments

  // Connect registers to outputs to preserve them for verification
  io.b0 := b0
  io.b1 := b1
  io.b2 := b2
  io.b3 := b3
  io.r0 := r0
  io.r1 := r1
  io.r2 := r2
  io.r3 := r3

  // === FORMAL ASSERTIONS ===

  // Safety: The valid invariant, which defines the cyclic consistency condition
  // between barrel shifter (b0-b3) and register file (r0-r3), must always hold.
  // This is the core architectural invariant: if b_i matches some r_j, then
  // b_{i+1} must match r_{j+1} (with wrap-around), ensuring the matching
  // between the two register sets respects a cyclic permutation.
  fvAssert(valid(b0, r0, b1, r1, b2, r2, b3, r3), "valid_invariant")

  // Safety: The register file holds its contents perpetually (never changes).
  // Since r0-r3 are RegInit with no further assignments, they should remain
  // stable at their initial value forever.
  assertStable(r0, "r0_stable")
  assertStable(r1, "r1_stable")
  assertStable(r2, "r2_stable")
  assertStable(r3, "r3_stable")

  // Liveness: The barrel shifter rotates its contents every cycle, completing
  // a full period every 4 cycles. Verify that after 4 cycles the barrel
  // returns to its configuration at the reference cycle.
  // Capture a snapshot of b registers for periodicity checking.
  val b_snapshot = RegInit(VecInit(Seq.fill(4)(0.U(2.W))))
  b_snapshot(0) := b0
  b_snapshot(1) := b1
  b_snapshot(2) := b2
  b_snapshot(3) := b3

  assertAt(4.U, b0 === b_snapshot(0) && b1 === b_snapshot(1) &&
                 b2 === b_snapshot(2) && b3 === b_snapshot(3), "barrel_period_4")

  // Safety: The rotation step is consistent. After one cycle, b3 should
  // equal the value that b0 had at the previous cycle (captured by b0_old).
  // This verifies that the barrel rotation wiring is correct.
  assertNextStepWhen(true.B, b3 === b0_old, "rotation_step_b3_gets_old_b0")
}

object VerilogGenerator extends App {
  emitVerilog(new barrel4(), args)
}
